<script setup>import { ref } from 'vue'; import { useRouter } from 'vue-router'; import api from '@/api/client'; const router=useRouter(); const plate=ref(''); const phone=ref(''); const error=ref(''); async function submit(){error.value=''; try{const {data}=await api.post('/public/track/lookup',{plate_number:plate.value,phone_last4:phone.value}); router.push(`/track/${data.data.tracking_code}`)}catch(e){error.value=e.response?.data?.message||'Data pelacakan tidak ditemukan.'}}</script><template><section><h1>Lacak servis kendaraan</h1><form @submit.prevent="submit" class="vstack gap-3" style="max-width:28rem"><label>Nomor plat<input v-model="plate" required class="form-control"></label><label>4 digit terakhir telepon<input v-model="phone" required pattern="[0-9]{4}" class="form-control"></label><button class="btn btn-primary">Cari kendaraan</button><p v-if="error" class="text-danger">{{ error }}</p></form></section></template>